157		s.mu.Lock()
158		defer s.mu.Unlock()
159		old, ok := s.subs[id]
160		if !ok || old.OrgID != orgID {
161			return Subscription{}, ErrNotFound
162		}
163		sub := copySub(old)
164		if err := f(&sub); err != nil {
165			return Subscription{}, err
166		}
167		sub.ID, sub.OrgID, sub.CustomerID, sub.CreatedAt = old.ID, old.OrgID, old.CustomerID, old.CreatedAt
168		if sub.Quantity <= 0 {
169			return Subscription{}, invalid("the quantity must be at least 1")
170		}
171		if p, ok := s.plans[sub.PlanID]; !ok || p.OrgID != orgID {
172			return Subscription{}, ErrNotFound
173		}
174		s.subs[id] = sub
175		return copySub(sub), nil
176	}
177	
178	// DueSubscriptions returns the subscriptions of every organization whose current period has ended by now and that are not
179	// canceled, the longest overdue first.
180	func (s *Store) DueSubscriptions(now time.Time) []Subscription {
181		s.mu.Lock()
182		defer s.mu.Unlock()
183		out := []Subscription{}
184		for _, sub := range s.subs {
185			if sub.Status != Canceled && !sub.CurrentPeriodEnd.After(now) {
186				out = append(out, copySub(sub))
187			}
188		}
189		sort.Slice(out, func(i, j int) bool {
190			if !out[i].CurrentPeriodEnd.Equal(out[j].CurrentPeriodEnd) {
191				return out[i].CurrentPeriodEnd.Before(out[j].CurrentPeriodEnd)
192			}
193			return out[i].ID < out[j].ID
194		})
195		return out
196	}
197	
198	func copySub(sub Subscription) Subscription {
199		if sub.TrialEnd != nil {
200			t := *sub.TrialEnd
201			sub.TrialEnd = &t
202		}
203		if sub.CanceledAt != nil {
204			t := *sub.CanceledAt
205			sub.CanceledAt = &t
206		}
207		return sub
208	}
209	
210	// AddUsage records usage of a subscription to a metered plan at time at.
211	func (s *Store) AddUsage(orgID, subID string, quantity int64, at, now time.Time) (UsageRecord, error) {
212		if quantity <= 0 {
213			return UsageRecord{}, invalid("usage must be a positive quantity")
214		}
215		s.mu.Lock()
216		defer s.mu.Unlock()
217		sub, ok := s.subs[subID]
218		if !ok || sub.OrgID != orgID {
219			return UsageRecord{}, ErrNotFound
220		}
221		if p := s.plans[sub.PlanID]; p.UsageType != Metered {
222			return UsageRecord{}, invalid("the subscription's plan is not metered")
223		}
224		u := UsageRecord{ID: s.newID("use"), OrgID: orgID, SubscriptionID: subID, Quantity: quantity, At: at.UTC(), CreatedAt: now.UTC()}
225		s.usage = append(s.usage, u)
226		return u, nil
227	}
228	
229	// UsageTotal adds up a subscription's usage at times in [from, to).
230	func (s *Store) UsageTotal(orgID, subID string, from, to time.Time) int64 {
231		s.mu.Lock()
232		defer s.mu.Unlock()
233		var n int64
234		for _, u := range s.usage {
235			if u.OrgID == orgID && u.SubscriptionID == subID && !u.At.Before(from) && u.At.Before(to) {
236				n += u.Quantity
237			}
238		}
239		return n
240	}
