291	// InvoiceByID returns an invoice of any organization (background jobs and the admin tool).
292	func (s *Store) InvoiceByID(id string) (Invoice, bool) {
293		s.mu.Lock()
294		defer s.mu.Unlock()
295		inv, ok := s.invoices[id]
296		return copyInvoice(inv), ok
297	}
