// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
// due; an unavailable gateway leaves the invoice open and the subscription's status as it was. Each period is renewed once,
// however many calls run at the same time or after each other. RenewDue goes on past a subscription that fails and returns
// the errors together at the end; it returns how many subscriptions it renewed or canceled.
func (s *Service) RenewDue(ctx context.Context) (int, error) {
	now := s.Clock.Now()
	n := 0
	var errs []error
	for _, sub := range s.Store.DueSubscriptions(now) {
		if err := ctx.Err(); err != nil {
			return n, errors.Join(append(errs, err)...)
		}
		renewed, err := s.renew(ctx, sub, now)
		if renewed {
			n++
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
		}
	}
	return n, errors.Join(errs...)
}

// renew renews one subscription. It reports whether this call renewed it; a subscription that another call has already
// renewed or canceled is left alone.
func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
	plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
	if !ok {
		return false, store.ErrNotFound
	}
	if sub.CancelAtPeriodEnd {
		end := sub.CurrentPeriodEnd
		canceled, claimed, err := s.claim(sub, func(x *store.Subscription) {
			x.Status, x.CanceledAt = store.Canceled, &end
		})
		if err != nil || !claimed {
			return false, err
		}
		s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
		return true, nil
	}
	// The period is claimed before anything is invoiced, so a second call finds it moved and does nothing. If the invoice
	// cannot be created the claim is undone, so the next call tries again; once the invoice exists the period stays moved.
	start := now
	end := billing.AddInterval(start, plan.Interval)
	renewed, claimed, err := s.claim(sub, func(x *store.Subscription) {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
	})
	if err != nil || !claimed {
		return false, err
	}
	ps, pe := start, end
	billed := false
	switch {
	case plan.UsageType == store.Metered && sub.Status != store.Trialing:
		ps, pe, billed = sub.CurrentPeriodStart, sub.CurrentPeriodEnd, true
	case plan.UsageType == store.Licensed:
		billed = true
	}
	status, payErr := store.Active, error(nil)
	if billed {
		inv, err := s.createPeriodInvoice(ctx, sub, plan, ps, pe)
		if err != nil {
			return false, errors.Join(err, s.unclaim(sub))
		}
		paid, err := s.payPeriodInvoice(ctx, inv)
		switch {
		case err != nil:
			// The invoice stays open to be paid later, and the status stays as it was.
			status, payErr = renewed.Status, err
		case !paid:
			status = store.PastDue
		}
	}
	if _, err := s.setStatus(ctx, renewed, status); err != nil {
		return true, errors.Join(payErr, err)
	}
	return true, payErr
}

// claim changes a subscription only while its period is still the one the caller read. It reports false, and changes
// nothing, when another call has moved the period on or the subscription was canceled.
func (s *Service) claim(sub store.Subscription, change func(*store.Subscription)) (store.Subscription, bool, error) {
	var moved bool
	claimed, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
		if x.Status == store.Canceled || !x.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !x.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
			moved = true
			return nil
		}
		change(x)
		return nil
	})
	if err != nil || moved {
		return store.Subscription{}, false, err
	}
	return claimed, true, nil
}

// unclaim puts back the period that renew claimed, for when its invoice could not be created.
func (s *Service) unclaim(claimed store.Subscription) error {
	_, err := s.Store.UpdateSubscription(claimed.OrgID, claimed.ID, func(x *store.Subscription) error {
		x.CurrentPeriodStart, x.CurrentPeriodEnd = claimed.CurrentPeriodStart, claimed.CurrentPeriodEnd
		return nil
	})
	return err
}

