cat >> internal/subscriptions/subscriptions_test.go <<'EOF'

// subscribeWith starts a licensed subscription of Acme's customer, who pays with paymentMethod, and returns it. The
// customer's payment method can be changed afterwards with setPaymentMethod.
func subscribeWith(t *testing.T, e *apitest.Env, paymentMethod string) store.Subscription {
	t.Helper()
	c := e.CreateCustomer(e.Acme, "Jane", "jane@example.com")
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, c.ID, func(c *store.Customer) error { c.DefaultPaymentMethod = paymentMethod; return nil })
	p := e.CreatePlan(e.Acme, "Team", "USD", "20.00")
	sub, err := e.Subs.Create(context.Background(), e.Acme.ID, subscriptions.CreateInput{CustomerID: c.ID, PlanID: p.ID, Quantity: 1})
	if err != nil {
		t.Fatal(err)
	}
	return sub
}

func setPaymentMethod(e *apitest.Env, sub store.Subscription, paymentMethod string) {
	_, _ = e.Store.UpdateCustomer(e.Acme.ID, sub.CustomerID, func(c *store.Customer) error { c.DefaultPaymentMethod = paymentMethod; return nil })
}

func TestConcurrentRenewalsInvoiceAndChargeOnce(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := subscribeWith(t, e, "pm_card_visa")
	// Hold each charge a moment, so that calls which read the subscription before it moved on have time to act on it.
	e.Gateway.OnCharge = func(payments.ChargeRequest) { time.Sleep(20 * time.Millisecond) }
	e.Clock.Set(sub.CurrentPeriodEnd)
	var renewed atomic.Int64
	var wg sync.WaitGroup
	for range 8 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n, err := e.Subs.RenewDue(ctx)
			if err != nil {
				t.Error(err)
			}
			renewed.Add(int64(n))
		}()
	}
	wg.Wait()
	if renewed.Load() != 1 {
		t.Fatalf("renewed %d times, want once", renewed.Load())
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || !invs[1].PeriodStart.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("invoices = %+v, want the first and one renewal", invs)
	}
	if cs := e.Gateway.Charges(); len(cs) != 2 {
		t.Fatalf("charges = %d, want the first period and one renewal", len(cs))
	}
}

func TestGatewayDownRenewalMovesOnAndLeavesInvoiceOpen(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := subscribeWith(t, e, "pm_card_visa")
	setPaymentMethod(e, sub, "pm_gateway_down")
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); !errors.Is(err, payments.ErrUnavailable) || n != 1 {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.Active || !got.CurrentPeriodStart.Equal(sub.CurrentPeriodEnd) || !got.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd.AddDate(0, 1, 0)) {
		t.Fatalf("after the outage = %+v", got)
	}
	invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID})
	if len(invs) != 2 || invs[1].Status != store.InvoiceOpen {
		t.Fatalf("invoices = %+v, want the renewal open", invs)
	}
	// The period has moved on, so later runs leave it alone, gateway working or not.
	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("second RenewDue = %d, %v", n, err)
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: sub.ID}); len(invs) != 2 {
		t.Fatalf("invoices after the second run = %d, want 2", len(invs))
	}
	if calls := e.Gateway.Calls(); len(calls) != 2 {
		t.Fatalf("charge attempts = %d, want the first period and one renewal", len(calls))
	}
}

func TestDeclinedRenewalIsPastDue(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	sub := subscribeWith(t, e, "pm_card_visa")
	setPaymentMethod(e, sub, "pm_card_declined")
	e.Clock.Set(sub.CurrentPeriodEnd)
	if n, err := e.Subs.RenewDue(ctx); n != 1 || err != nil {
		t.Fatalf("RenewDue = %d, %v", n, err)
	}
	got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
	if got.Status != store.PastDue || !got.CurrentPeriodStart.Equal(sub.CurrentPeriodEnd) {
		t.Fatalf("after the decline = %+v", got)
	}
	if n, err := e.Subs.RenewDue(ctx); n != 0 || err != nil {
		t.Fatalf("second RenewDue = %d, %v", n, err)
	}
}

func TestOneFailureDoesNotStopOtherRenewals(t *testing.T) {
	e := apitest.New(t)
	ctx := context.Background()
	down := subscribeWith(t, e, "pm_card_visa")
	setPaymentMethod(e, down, "pm_gateway_down")
	up := subscribeWith(t, e, "pm_card_visa")
	e.Clock.Set(up.CurrentPeriodEnd)
	n, err := e.Subs.RenewDue(ctx)
	if !errors.Is(err, payments.ErrUnavailable) || n != 2 {
		t.Fatalf("RenewDue = %d, %v; want both renewed and the outage reported", n, err)
	}
	for _, sub := range []store.Subscription{down, up} {
		got, _ := e.Store.Subscription(e.Acme.ID, sub.ID)
		if !got.CurrentPeriodStart.Equal(sub.CurrentPeriodEnd) {
			t.Fatalf("%s was not renewed: %+v", sub.ID, got)
		}
	}
	if invs := e.Store.ListInvoices(e.Acme.ID, store.InvoiceFilter{SubscriptionID: up.ID, Status: store.InvoicePaid}); len(invs) != 2 {
		t.Fatalf("the other subscription's renewal was not paid: %+v", invs)
	}
}
EOF
