	gw := &payments.Fake{}
	s := &Service{Store: st, Payments: &payments.Service{Store: st, Gateway: gw, Clock: clk}, Clock: clk}

	org, err := st.CreateOrg("Acme", store.OrgTeam, "UTC", 0, now)
	if err != nil {
		t.Fatal(err)
	}
	c, err := st.CreateCustomer(org.ID, "Jane", "jane@example.com", now)
	if err != nil {
		t.Fatal(err)
	}
