1	// Package subscriptions runs subscriptions: starting them with their first invoice, changing and canceling them, and
2	// renewing them when a billing period ends.
3	package subscriptions
4	
5	import (
6		"context"
7		"errors"
8		"fmt"
9		"time"
10	
11		"example.com/tally/internal/billing"
12		"example.com/tally/internal/clock"
13		"example.com/tally/internal/payments"
14		"example.com/tally/internal/store"
15	)
16	
17	// Errors.
18	var (
19		ErrPlanInactive = errors.New("the plan is not active")
20		ErrCanceled     = errors.New("the subscription is canceled")
21	)
22	
23	// Service runs subscriptions.
24	type Service struct {
25		Store     *store.Store
26		Payments  *payments.Service
27		Clock     clock.Clock
28		Publisher payments.Publisher // nil: no events
29	}
30	
31	// CreateInput is a new subscription.
32	type CreateInput struct {
33		CustomerID      string
34		PlanID          string
35		Quantity        int // 0 means 1
36		DiscountPercent int
37	}
38	
39	// Create starts a subscription now. With a plan that has a trial, the subscription is trialing until the trial ends, and
40	// its first period starts then. Otherwise its first period starts now; for a licensed plan that period is invoiced at once
41	// and charged to the customer's default payment method, if it has one (a declined charge makes the subscription past due).
42	func (s *Service) Create(ctx context.Context, orgID string, in CreateInput) (store.Subscription, error) {
43		plan, ok := s.Store.Plan(orgID, in.PlanID)
44		if !ok {
45			return store.Subscription{}, store.ErrNotFound
46		}
47		if !plan.Active {
48			return store.Subscription{}, ErrPlanInactive
49		}
50		if in.Quantity == 0 {
51			in.Quantity = 1
52		}
53		now := s.Clock.Now()
54		sub := store.Subscription{OrgID: orgID, CustomerID: in.CustomerID, PlanID: plan.ID, Quantity: in.Quantity, DiscountPercent: in.DiscountPercent,
55			StartedAt: now, CurrentPeriodStart: now}
56		if plan.TrialDays > 0 {
57			end := now.AddDate(0, 0, plan.TrialDays)
58			sub.Status, sub.TrialEnd, sub.CurrentPeriodEnd = store.Trialing, &end, end
59		} else {
60			sub.Status, sub.CurrentPeriodEnd = store.Active, billing.AddInterval(now, plan.Interval)
61		}
62		sub, err := s.Store.CreateSubscription(sub, now)
63		if err != nil {
64			return store.Subscription{}, err
65		}
66		s.publish(ctx, orgID, "subscription.created", sub)
67		if sub.Status == store.Active && plan.UsageType == store.Licensed {
68			paid, err := s.invoicePeriod(ctx, sub, plan, sub.CurrentPeriodStart, sub.CurrentPeriodEnd)
69			if err != nil {
70				return sub, err
71			}
72			if !paid {
73				if sub, err = s.setStatus(ctx, sub, store.PastDue); err != nil {
74					return sub, err
75				}
76			}
77		}
78		return sub, nil
79	}
80	
81	// UpdateInput changes a subscription; nil fields stay as they are.
82	type UpdateInput struct {
83		PlanID   *string
84		Quantity *int
85	}
86	
87	// Update changes a subscription's plan or quantity. The change applies at once and is billed from the next period on.
88	func (s *Service) Update(ctx context.Context, orgID, id string, in UpdateInput) (store.Subscription, error) {
89		if in.PlanID != nil {
90			p, ok := s.Store.Plan(orgID, *in.PlanID)
91			if !ok {
92				return store.Subscription{}, store.ErrNotFound
93			}
94			if !p.Active {
95				return store.Subscription{}, ErrPlanInactive
96			}
97		}
98		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
99			if sub.Status == store.Canceled {
100				return ErrCanceled
101			}
102			if in.PlanID != nil {
103				sub.PlanID = *in.PlanID
104			}
105			if in.Quantity != nil {
106				sub.Quantity = *in.Quantity
107			}
108			return nil
109		})
110		if err != nil {
111			return store.Subscription{}, err
112		}
113		s.publish(ctx, orgID, "subscription.updated", sub)
114		return sub, nil
115	}
116	
117	// Cancel cancels a subscription now, or at the end of its current period when atPeriodEnd is set. Canceling a canceled
118	// subscription changes nothing.
119	func (s *Service) Cancel(ctx context.Context, orgID, id string, atPeriodEnd bool) (store.Subscription, error) {
120		now := s.Clock.Now()
121		sub, err := s.Store.UpdateSubscription(orgID, id, func(sub *store.Subscription) error {
122			if sub.Status == store.Canceled {
123				return nil
124			}
125			if atPeriodEnd {
126				sub.CancelAtPeriodEnd = true
127				return nil
128			}
129			sub.Status, sub.CanceledAt = store.Canceled, &now
130			return nil
131		})
132		if err != nil {
133			return store.Subscription{}, err
134		}
135		if sub.Status == store.Canceled {
136			s.publish(ctx, orgID, "subscription.canceled", sub)
137		} else {
138			s.publish(ctx, orgID, "subscription.updated", sub)
139		}
140		return sub, nil
141	}
142	
143	// RenewDue renews every subscription, of every organization, whose current period has ended. A subscription set to cancel
144	// at the end of its period is canceled. Otherwise its next period starts and is invoiced: a licensed plan bills the new
145	// period in advance, a metered plan bills the usage of the period that ended. A declined charge makes the subscription past
146	// due; an unavailable gateway leaves the invoice open and the subscription's status as it was. Each period is renewed once,
147	// however many calls run at the same time or after each other. RenewDue goes on past a subscription that fails and returns
148	// the errors together at the end; it returns how many subscriptions it renewed or canceled.
149	func (s *Service) RenewDue(ctx context.Context) (int, error) {
150		now := s.Clock.Now()
151		n := 0
152		var errs []error
153		for _, sub := range s.Store.DueSubscriptions(now) {
154			if err := ctx.Err(); err != nil {
155				return n, errors.Join(append(errs, err)...)
156			}
157			renewed, err := s.renew(ctx, sub, now)
158			if renewed {
159				n++
160			}
161			if err != nil {
162				errs = append(errs, fmt.Errorf("renew %s: %w", sub.ID, err))
163			}
164		}
165		return n, errors.Join(errs...)
166	}
167	
168	// renew renews one subscription. It reports whether this call renewed it; a subscription that another call has already
169	// renewed or canceled is left alone.
170	func (s *Service) renew(ctx context.Context, sub store.Subscription, now time.Time) (bool, error) {
171		plan, ok := s.Store.Plan(sub.OrgID, sub.PlanID)
172		if !ok {
173			return false, store.ErrNotFound
174		}
175		if sub.CancelAtPeriodEnd {
176			end := sub.CurrentPeriodEnd
177			canceled, claimed, err := s.claim(sub, func(x *store.Subscription) {
178				x.Status, x.CanceledAt = store.Canceled, &end
179			})
180			if err != nil || !claimed {
181				return false, err
182			}
183			s.publish(ctx, sub.OrgID, "subscription.canceled", canceled)
184			return true, nil
185		}
186		// The period is claimed before anything is invoiced, so a second call finds it moved and does nothing. If the invoice
187		// cannot be created the claim is undone, so the next call tries again; once the invoice exists the period stays moved.
188		start := now
189		end := billing.AddInterval(start, plan.Interval)
190		renewed, claimed, err := s.claim(sub, func(x *store.Subscription) {
191			x.CurrentPeriodStart, x.CurrentPeriodEnd = start, end
192		})
193		if err != nil || !claimed {
194			return false, err
195		}
196		ps, pe := start, end
197		billed := false
198		switch {
199		case plan.UsageType == store.Metered && sub.Status != store.Trialing:
200			ps, pe, billed = sub.CurrentPeriodStart, sub.CurrentPeriodEnd, true
201		case plan.UsageType == store.Licensed:
202			billed = true
203		}
204		status := store.Active
205		var payErr error
206		if billed {
207			inv, err := s.createPeriodInvoice(ctx, sub, plan, ps, pe)
208			if err != nil {
209				return false, errors.Join(err, s.unclaim(sub))
210			}
211			paid, err := s.payPeriodInvoice(ctx, inv)
212			switch {
213			case err != nil:
214				// The invoice stays open to be paid later, and the status stays as it was.
215				status, payErr = renewed.Status, err
216			case !paid:
217				status = store.PastDue
218			}
219		}
220		if _, err := s.setStatus(ctx, renewed, status); err != nil {
221			return true, errors.Join(payErr, err)
222		}
223		return true, payErr
224	}
225	
226	// claim changes a subscription only while its period is still the one the caller read. It reports false, and changes
227	// nothing, when another call has moved the period on or the subscription was canceled.
228	func (s *Service) claim(sub store.Subscription, change func(*store.Subscription)) (store.Subscription, bool, error) {
229		var moved bool
230		claimed, err := s.Store.UpdateSubscription(sub.OrgID, sub.ID, func(x *store.Subscription) error {
231			if x.Status == store.Canceled || !x.CurrentPeriodStart.Equal(sub.CurrentPeriodStart) || !x.CurrentPeriodEnd.Equal(sub.CurrentPeriodEnd) {
232				moved = true
233				return nil
234			}
235			change(x)
236			return nil
237		})
238		if err != nil || (moved && false) {
239			return store.Subscription{}, false, err
240		}
241		return claimed, true, nil
242	}
243	
244	// unclaim puts back the period that renew claimed, for when its invoice could not be created.
245	func (s *Service) unclaim(claimed store.Subscription) error {
246		_, err := s.Store.UpdateSubscription(claimed.OrgID, claimed.ID, func(x *store.Subscription) error {
247			x.CurrentPeriodStart, x.CurrentPeriodEnd = claimed.CurrentPeriodStart, claimed.CurrentPeriodEnd
248			return nil
249		})
250		return err
251	}
252	
253	// invoicePeriod invoices one period of a subscription and charges the invoice to the customer's default payment method.
254	// It reports false when the charge was declined. An invoice that needs no charge is marked paid; one whose customer has no
255	// payment method stays open and counts as paid here (it is paid by hand).
256	func (s *Service) invoicePeriod(ctx context.Context, sub store.Subscription, plan store.Plan, start, end time.Time) (bool, error) {
257		inv, err := s.createPeriodInvoice(ctx, sub, plan, start, end)
258		if err != nil {
259			return false, err
260		}
261		return s.payPeriodInvoice(ctx, inv)
262	}
263	
264	// createPeriodInvoice creates the open invoice for one period of a subscription.
